import json,os
def transform(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    dirs={'down':[(1,1),(1,-1)],'up':[(-1,1),(-1,-1)]}
    for name,(d1,d2) in dirs.items():
        for r in range(H):
            for c in range(W):
                if g[r][c]==0: continue
                # collect ray cells for each direction
                rays=[]
                for dr,dc in (d1,d2):
                    cells=[]; rr,cc=r+dr,c+dc
                    while 0<=rr<H and 0<=cc<W:
                        cells.append((rr,cc)); rr+=dr; cc+=dc
                    rays.append(cells)
                n=min(len(rays[0]),len(rays[1]))
                for k in range(n):
                    (ra,ca),(rb,cb)=rays[0][k],rays[1][k]
                    assert ra==rb
                    lo,hi=min(ca,cb),max(ca,cb)
                    for cc in range(lo+1,hi):
                        out[ra][cc]=2
    return out
